use std :: process :: Command ; use std :: env ; use std :: ffi :: OsString ; use std :: sync :: { LazyLock , Mutex , MutexGuard } ; use super :: * ; # [doc = " Checks if the Forge VS Code extension is installed"] # [doc = ""] # [doc = " Checks VS Code's extension list to see if ForgeCode.forge-vscode is"] # [doc = " installed."] pub fn is_extension_installed () -> bool { if let Ok (output) = Command :: new ("code") . arg ("--list-extensions") . output () && output . status . success () && let Ok (extensions) = String :: from_utf8 (output . stdout) { return extensions . lines () . any (| line | line . trim () == "ForgeCode.forge-vscode") ; } false }